ValidationRule.errorConditionFormula:
AND(
$RecordType.DeveloperName = "Excelitas_Sales_Opportunity", OR( ISPICKVAL(Division__c, "Semiconductor Equipment"), ISPICKVAL(Division__c, "Advanced Industrial Sensing"), ISPICKVAL(Division__c, "MedTech & Life Sciences"), ISPICKVAL(Division__c, "Advanced Lighting Systems"), ISPICKVAL(Division__c, "Integrated Optronics & Avionics") ), OR( AND( OR( ISPICKVAL(Division__c, "Semiconductor Equipment"), ISPICKVAL(Division__c, "Advanced Industrial Sensing"), ISPICKVAL(Division__c, "MedTech & Life Sciences") ), NOT( OR( ISPICKVAL(StageName, "1 - Opportunity Validation")
) ) ), ISPICKVAL(Division__c, "Advanced Lighting Systems"), ISPICKVAL(Division__c, "Integrated Optronics & Avionics") ), OR( ISBLANK(TEXT(Business_Unit__c)), ISBLANK(TEXT(Product_LineGlobal__c)) ) )
